const item = $input.first().json;
if (item.error) {
  console.log('Topic history fetch failed, continuing with empty history:', item.error);
  return { json: { topics: [] } };
}
if (!Array.isArray(item.topics)) {
  console.log('Topic history response missing topics array, defaulting to empty');
  return { json: { topics: [] } };
}
return { json: { topics: item.topics } };

const response = $input.first().json;
if (response.error) {
  throw new Error('Claude API returned an error: ' + JSON.stringify(response.error));
}
// With extended thinking enabled, content[0] is a 'thinking' block, not
// 'text' - the actual answer is the first block with type === 'text'.
const textBlock = (response.content || []).find(b => b.type === 'text');
let raw = textBlock?.text;
if (!raw || raw.trim() === '') {
  throw new Error('Claude did not return a topic - check the "Claude: Generate Topic" node response');
}
if (response.stop_reason === 'max_tokens') {
  console.log('Warning: topic generation hit max_tokens, response may be truncated');
}
raw = raw.trim().replace(/^```(?:\w*)?\s*/i, '').replace(/```\s*$/, '').trim();
const topic = raw.replace(/^["']|["']$/g, '');
if (topic.length < 10) {
  throw new Error('Generated topic looks too short/empty to be usable: "' + topic + '"');
}
return { json: { topic } };

const response = $input.first().json;
if (response.error) {
  throw new Error('Claude API returned an error: ' + JSON.stringify(response.error));
}
let raw = response.content?.[0]?.text;
if (!raw) throw new Error('Claude draft response missing content[0].text');
if (response.stop_reason === 'max_tokens') {
  throw new Error('Claude draft was cut off by max_tokens - the script is likely truncated mid-JSON. Increase max_tokens on the "Claude: Draft Script (Stage 1)" node.');
}

// Strip markdown code fences if present (Claude sometimes wraps JSON in ```json ... ``` despite instructions not to)
raw = raw.trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}
// Stage 1 is called with an assistant prefill of "{", so the model returns
// JSON only (no analysis preamble). Repair defensively: try the raw text,
// the prefill-completed text, and a balanced {...} extraction; use whichever
// first yields a valid object.
function extractJsonObject(s) {
  const at = s.indexOf('{');
  if (at === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = at; i < s.length; i++) {
    const cc = s.charCodeAt(i);
    if (inStr) {
      if (esc) esc = false;
      else if (cc === 92) esc = true;
      else if (cc === 34) inStr = false;
    } else if (cc === 34) inStr = true;
    else if (cc === 123) depth++;
    else if (cc === 125) { depth--; if (depth === 0) return s.slice(at, i + 1); }
  }
  return null;
}
function tryParse(s) {
  if (!s || typeof s !== 'string') return undefined;
  try { const v = JSON.parse(s); return (v && typeof v === 'object') ? v : undefined; } catch (e) { return undefined; }
}
const parsed = tryParse(raw) || tryParse('{' + raw) || tryParse(extractJsonObject('{' + raw)) || tryParse(extractJsonObject(raw));
if (!parsed) {
  throw new Error('Claude draft did not return valid JSON: ' + raw.slice(0, 300));
}
return { json: { draft: parsed } };

const response = $input.first().json;
if (response.error) {
  throw new Error('Claude API returned an error: ' + JSON.stringify(response.error));
}
let raw = response.content?.[0]?.text;
if (!raw) throw new Error('Claude editor response missing content[0].text');
if (response.stop_reason === 'max_tokens') {
  throw new Error('Claude editorial rewrite was cut off by max_tokens - likely truncated mid-JSON. Increase max_tokens on the "Claude: Editorial Rewrite (Stage 2)" node.');
}
raw = raw.trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}
// Stage 2 is called with an assistant prefill of "{", so the model returns
// JSON only (no analysis preamble). Repair defensively: try the raw text,
// the prefill-completed text, and a balanced {...} extraction; use whichever
// first yields a valid object.
function extractJsonObject(s) {
  const at = s.indexOf('{');
  if (at === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = at; i < s.length; i++) {
    const cc = s.charCodeAt(i);
    if (inStr) {
      if (esc) esc = false;
      else if (cc === 92) esc = true;
      else if (cc === 34) inStr = false;
    } else if (cc === 34) inStr = true;
    else if (cc === 123) depth++;
    else if (cc === 125) { depth--; if (depth === 0) return s.slice(at, i + 1); }
  }
  return null;
}
function tryParse(s) {
  if (!s || typeof s !== 'string') return undefined;
  try { const v = JSON.parse(s); return (v && typeof v === 'object') ? v : undefined; } catch (e) { return undefined; }
}
const parsed = tryParse(raw) || tryParse('{' + raw) || tryParse(extractJsonObject('{' + raw)) || tryParse(extractJsonObject(raw));
if (!parsed) {
  throw new Error('Claude editor did not return valid JSON: ' + raw.slice(0, 300));
}

const errors = [];
if (!parsed.hook || parsed.hook.length < 5 || parsed.hook.length > 200) {
  errors.push('hook missing or out of bounds (5-200 chars)');
}
if (parsed.hook_candidates !== undefined) {
  if (!Array.isArray(parsed.hook_candidates) || parsed.hook_candidates.length < 3 || parsed.hook_candidates.length > 6) {
    errors.push('hook_candidates, if present, must be an array of 3-6 strings');
  }
}
if (!parsed.title || parsed.title.length < 5 || parsed.title.length > 50) {
  errors.push('title missing or out of bounds (5-50 chars) - kept short for mobile-screen fit');
}
const validCaptionStyles = ['upbeat', 'serious', 'funny', 'neutral'];
if (!validCaptionStyles.includes(parsed.caption_style)) {
  errors.push('caption_style must be one of: ' + validCaptionStyles.join(', '));
}
if (!Array.isArray(parsed.tags) || parsed.tags.length < 5 || parsed.tags.length > 20) {
  errors.push('tags must be an array of 5-20 strings');
}
if (!parsed.seo_description || parsed.seo_description.length < 20) {
  errors.push('seo_description missing or too short');
}
if (!parsed.comment_hook || parsed.comment_hook.length < 8) {
  errors.push('comment_hook missing or too short');
}
const genericCommentHooks = /^(what do you think|comment below|let us know|tell us|do you agree)/i;
if (parsed.comment_hook && genericCommentHooks.test(parsed.comment_hook.trim())) {
  errors.push('comment_hook is too generic - must be specific to this exact fact, not a generic prompt');
}

// Risky-visual keyword heuristic: catches shots that would need the AI video
// model to render readable text/numbers - the exact defect that made two
// prior videos look like obvious "AI slop" (garbled fake documents/money).
const riskyPatterns = [
  /readable/i, /legible/i, /visible text/i, /text visible/i, /showing the (total|amount|number|price)/i,
  /screen (showing|displaying)/i, /receipt (with|showing)/i, /document (with|showing)/i,
  /denomination/i, /close-?up of.*(document|receipt|form|paperwork).*text/i, /id card/i,
  /spreadsheet/i, /calculator display/i, /\$[0-9]/,
];

if (!Array.isArray(parsed.scenes) || parsed.scenes.length < 4 || parsed.scenes.length > 8) {
  errors.push('scenes must be an array of 4-8 items');
} else {
  let totalWords = 0;
  parsed.scenes.forEach((s, i) => {
    if (typeof s.scene_index !== 'number') errors.push(`scene ${i} missing numeric scene_index`);
    if (!s.point || s.point.length < 3) errors.push(`scene ${i} missing point field`);
    if (!s.narration || s.narration.length < 5) errors.push(`scene ${i} narration too short/missing`);
    if (s.visual_source !== 'template') {
      if (!s.visual_prompt || s.visual_prompt.length < 20) errors.push(`scene ${i} visual_prompt too short/missing`);
      if (!s.negative_prompt) errors.push(`scene ${i} missing negative_prompt`);
      if (!s.stock_search_query || s.stock_search_query.trim().length < 3) errors.push(`scene ${i} missing stock_search_query`);
    }
    if (s.visual_source === 'template') {
      const spec = {"stat_reveal":["statValue","label"],"comparison":["leftLabel","leftValue","rightLabel","rightValue"],"kinetic_text":["line"]}[s.template_name];
      if (!spec) {
        errors.push(`scene ${i} has unknown template_name "${s.template_name}" - must be one of stat_reveal, comparison, kinetic_text`);
      } else if (!s.template_data || typeof s.template_data !== 'object') {
        errors.push(`scene ${i} missing template_data object`);
      } else {
        for (const field of spec) {
          if (!s.template_data[field] || String(s.template_data[field]).trim().length < 1) {
            errors.push(`scene ${i} template_data missing required field "${field}" for template "${s.template_name}"`);
          }
        }
      }
    } else if (s.visual_source !== 'stock' && s.visual_source !== undefined) {
      errors.push(`scene ${i} visual_source must be "stock" or "template", got "${s.visual_source}"`);
    }

    if (s.narration) totalWords += s.narration.trim().split(/\s+/).length;

    if (s.visual_prompt) {
      for (const pattern of riskyPatterns) {
        if (pattern.test(s.visual_prompt)) {
          errors.push(`scene ${i} visual_prompt likely requires readable text/numbers in the AI-generated video (matched pattern: ${pattern}) - this reliably renders as garbled fake text. Rewrite to show the concept without legible text.`);
          break;
        }
      }
    }
    if (s.negative_prompt && !/text|legible|readable/i.test(s.negative_prompt)) {
      errors.push(`scene ${i} negative_prompt does not explicitly exclude readable text/numbers - required for every scene`);
    }
  });

  if (totalWords > 280) {
    errors.push(`total narration word count (${totalWords}) exceeds 280 word hard limit - too long even for a 60-90s Short (target is 170-240 words). Cut genuine padding.`);
  }
}


// Medical/health exclusion backstop - a best-effort keyword scan, not
// exhaustive, but catches obvious cases that slipped past both Claude passes.
const medicalKeywords = /\b(disease|illness|symptom|diagnos|treatment|medication|surgery|surgical|cancer|tumor|infection|virus|bacteria(?!l gut)|syndrome|disorder|therapy|prescription|patient|clinical|chronic pain|mental illness|depression|anxiety disorder|vaccine|antibiotic)\b/i;
const textToScan = [parsed.hook, parsed.title, ...(Array.isArray(parsed.scenes) ? parsed.scenes.map(s => s.narration || '') : [])].join(' ');
if (medicalKeywords.test(textToScan)) {
  errors.push('script appears to touch medical/health content (keyword match) - this content type is excluded, retry with a different topic');
}

if (errors.length > 0) {
  return { json: { _scriptValid: false, _validationErrors: errors } };
}

return { json: { ...parsed, _scriptValid: true } };

const item = $input.item.json;
const sceneIndex = $('Split Out Scenes').item.json.scene_index;
if (!item?.video?.url) {
  throw new Error(`fal.ai result for scene_index ${sceneIndex} is missing video.url. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
return { json: { scene_index: sceneIndex, video: item } };

const item = $input.item.json;
const sceneIndex = $('Split Out Scenes').item.json.scene_index;
if (!item?.audio_base64) {
  throw new Error(`ElevenLabs result for scene_index ${sceneIndex} is missing audio_base64. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
if (!item?.alignment) {
  throw new Error(`ElevenLabs result for scene_index ${sceneIndex} is missing alignment/timestamps - check that the "with-timestamps" endpoint is being used. Raw response: ` + JSON.stringify(item).slice(0, 500));
}
return { json: { scene_index: sceneIndex, audio: item } };

// This node is downstream of a real Merge node with TWO input connections
// (images + audio), so n8n guarantees both branches have fully completed
// before this runs - no race condition from cross-branch $() references.
const allItems = $input.all().map(i => i.json);

// Each scene's visual asset is EITHER a generated image array (.images) OR a
// template scene descriptor (.visual_source === 'template') - shape-detect
// on whichever field is present.
const imageAgg = allItems.find(i => Array.isArray(i.data) && i.data[0] && (i.data[0].images || i.data[0].video_url || i.data[0].visual_source === 'template'));
const audioAgg = allItems.find(i => Array.isArray(i.data) && i.data[0] && i.data[0].audio);

if (!imageAgg) throw new Error('Could not find the visual branch in merged input - check "Aggregate All Videos" output shape');
if (!audioAgg) throw new Error('Could not find the audio branch in merged input - check "Aggregate All Audio" output shape');

const visuals = imageAgg.data;
const audios = audioAgg.data;

const merged = visuals.map((v) => {
  const match = audios.find((a) => a.scene_index === v.scene_index);
  if (!match) {
    throw new Error(`No audio found for scene_index ${v.scene_index} - visual/audio counts likely mismatched`);
  }
  return {
    scene_index: v.scene_index,
    images: v.images,
    video_url: v.video_url,
    source_duration: v.source_duration,
    source_width: v.source_width,
    source_height: v.source_height,
    visual_source: v.visual_source,
    template_name: v.template_name,
    template_data: v.template_data,
    audio: match.audio,
  };
});

merged.sort((a, b) => a.scene_index - b.scene_index);

return {
  json: {
    hook: $('Validate Final Script').item.json.hook,
    comment_hook: $('Validate Final Script').item.json.comment_hook,
    full_script: $('Validate Final Script').item.json.full_script,
    caption_style: $('Validate Final Script').item.json.caption_style,
    data: merged
  }
};

const item = $input.first().json;
if (item.success !== true) {
  throw new Error('FFmpeg compose service reported failure: ' + (item.error || 'unknown error') + ' | job_id: ' + (item.job_id || 'unknown'));
}
if (!item.output_path) {
  throw new Error('FFmpeg compose response missing output_path even though success=true: ' + JSON.stringify(item).slice(0, 500));
}
return { json: item };

const prevAttempt = $('Init Script Attempt Counter').item.json.scriptAttempt ?? 0;
const newAttempt = prevAttempt + 1;
const errors = $input.first().json._validationErrors || [];
console.log(`Script validation failed on attempt ${newAttempt}: ${errors.join(' | ')}`);
return { json: { scriptAttempt: newAttempt, lastErrors: errors } };

const sceneIndex = $('Split Out Scenes').item.json.scene_index;
const imgs = $input.item.json.images || [];
if (!imgs.length || !imgs[0] || !imgs[0].url) {
  throw new Error(`fal.ai returned no image for scene_index ${sceneIndex}. Raw response: ` + JSON.stringify($input.item.json).slice(0, 400));
}
// One generated image per scene; buildImageScene applies the Ken Burns
// pan/zoom over it. The image is rendered from this scene's visual_prompt,
// so it matches the narration instead of being a loose stock match.
return { json: { scene_index: sceneIndex, images: [imgs[0].url], _source: 'fal_flux' } };

const scene = $('Split Out Scenes').item.json;
return {
  json: {
    scene_index: scene.scene_index,
    visual_source: 'template',
    template_name: scene.template_name,
    template_data: scene.template_data,
  }
};
